// A StaticSwitchParameter property is not a uniform: it expands into a reflected call wherever it is called.
/// @name M_LpStaticSwitch
export void M_LpStaticSwitch(inout material Base)
{
    float3 Color = float3(0, 0, 0);
    Color = UE.Expression(Class = "StaticSwitchParameter", ParameterName = "UseWarm", DefaultValue = true, Group = "Look", A = float3(1.0, 0.5, 0.0), B = float3(0.0, 0.5, 1.0));
    Base.EmissiveColor = Color;
}
